use anyhow::{ensure, Result};
use helper_functions::{accessors, misc, slot_report::SlotReport, verifier::Verifier};
use pubkey_cache::PubkeyCache;
use types::{
    config::Config,
    deneb::{
        beacon_state::BeaconState,
        containers::{BlindedBeaconBlock, BlindedBeaconBlockBody},
    },
    preset::Preset,
};

use super::block_processing;
use crate::{
    altair, capella,
    unphased::{self, Error},
};

#[cfg(feature = "metrics")]
use prometheus_metrics::METRICS;

pub fn custom_process_blinded_block<P: Preset>(
    config: &Config,
    pubkey_cache: &PubkeyCache,
    state: &mut BeaconState<P>,
    block: &BlindedBeaconBlock<P>,
    mut verifier: impl Verifier,
    mut slot_report: impl SlotReport,
) -> Result<()> {
    #[cfg(feature = "metrics")]
    let _timer = METRICS
        .get()
        .map(|metrics| metrics.blinded_block_transition_times.start_timer());

    debug_assert_eq!(state.slot, block.slot);

    unphased::process_block_header(config, state, block)?;

    // > [New in Capella]
    capella::process_withdrawals_root(state, &block.body.execution_payload_header)?;

    // > [Modified in Capella]
    process_execution_payload(config, state, &block.body)?;

    unphased::process_randao(config, pubkey_cache, state, &block.body, &mut verifier)?;
    unphased::process_eth1_data(state, &block.body)?;

    block_processing::process_operations(
        config,
        pubkey_cache,
        state,
        &block.body,
        &mut verifier,
        &mut slot_report,
    )?;

    altair::process_sync_aggregate(
        config,
        pubkey_cache,
        state,
        block.body.sync_aggregate,
        verifier,
        slot_report,
    )
}

fn process_execution_payload<P: Preset>(
    config: &Config,
    state: &mut BeaconState<P>,
    body: &BlindedBeaconBlockBody<P>,
) -> Result<()> {
    let payload_header = &body.execution_payload_header;

    let in_state = state.latest_execution_payload_header.block_hash;
    let in_block = payload_header.parent_hash;

    ensure!(
        in_state == in_block,
        Error::<P>::ExecutionPayloadParentHashMismatch { in_state, in_block },
    );

    let in_state = accessors::get_randao_mix(state, accessors::get_current_epoch(state));
    let in_block = payload_header.prev_randao;

    ensure!(
        in_state == in_block,
        Error::<P>::ExecutionPayloadPrevRandaoMismatch { in_state, in_block },
    );

    let computed = misc::compute_timestamp_at_slot(config, state, state.slot);
    let in_block = payload_header.timestamp;

    ensure!(
        computed == in_block,
        Error::<P>::ExecutionPayloadTimestampMismatch { computed, in_block },
    );

    state.latest_execution_payload_header = payload_header.clone();

    Ok(())

pub async fn publish_blinded_block<P: Preset, W: Wait>(
    State(block_producer): State<Arc<BlockProducer<P, W>>>,
    State(controller): State<ApiController<P, W>>,
    State(metrics): State<Option<Arc<Metrics>>>,
    State(api_to_p2p_tx): State<UnboundedSender<ApiToP2p<P>>>,
    EthJsonOrSszWithOptionalPhase(signed_blinded_block, _): EthJsonOrSszWithOptionalPhase<
        Box<SignedBlindedBeaconBlock<P>>,
        SignedBlindedBeaconPhaseDeserializer<P>,
    >,
) -> Result<StatusCode, Error> {
    let execution_payload = block_producer
        .publish_signed_blinded_block(&signed_blinded_block)
        .await;

    let WithBlobsAndMev {
        value: execution_payload,
        proofs,
        blobs,
        ..
    } = execution_payload
        .ok_or(Error::ExecutionPayloadNotAvailable)?
        .result;

    let (message, signature) = signed_blinded_block.split();

    let signed_beacon_block = message
        .with_execution_payload(execution_payload)
        .map_err(AnyhowError::new)?
        .with_signature(signature)
        .pipe(Arc::new);

    let slot = signed_beacon_block.to_header().message.slot;

    if controller
        .chain_config()
        .phase_at_slot::<P>(slot)
        .is_peerdas_activated()
    {
        let timer = metrics
            .as_ref()
            .map(|metrics| metrics.data_column_sidecar_computation.start_timer());

        let cells_and_kzg_proofs = eip_7594::try_convert_to_cells_and_kzg_proofs::<P>(
            blobs.unwrap_or_default().as_ref(),
            proofs.unwrap_or_else(KzgProofs::empty_fulu).as_ref(),
            controller.store_config().kzg_backend,
        )?;

        let data_column_sidecars =
            eip_7594::construct_data_column_sidecars(&signed_beacon_block, &cells_and_kzg_proofs)?;

        prometheus_metrics::stop_and_record(timer);

        publish_signed_block_with_data_column_sidecar(
            signed_beacon_block,
            data_column_sidecars,
            controller,
            api_to_p2p_tx,
        )
        .await
    } else {
        let blob_sidecars = misc::construct_blob_sidecars(
            &signed_beacon_block,
            blobs.unwrap_or_default().into_iter(),
            proofs.unwrap_or_else(KzgProofs::empty_deneb).into_iter(),
        )?;

        publish_signed_block(
            signed_beacon_block,
            blob_sidecars,
            controller,
            api_to_p2p_tx,
        )
        .await
    }
}

/// `POST /eth/v2/beacon/blinded_blocks`
pub async fn publish_blinded_block_v2<P: Preset, W: Wait>(
    State(block_producer): State<Arc<BlockProducer<P, W>>>,
    State(controller): State<ApiController<P, W>>,
    State(api_to_p2p_tx): State<UnboundedSender<ApiToP2p<P>>>,
    EthQuery(query): EthQuery<PublishBlockQuery>,
    EthJsonOrSsz(signed_blinded_block, _): EthJsonOrSsz<
        Box<SignedBlindedBeaconBlock<P>>,
        SignedBlindedBeaconPhaseDeserializer<P>,
    >,
) -> Result<StatusCode, Error> {
    let execution_payload = block_producer
        .publish_signed_blinded_block(&signed_blinded_block)
        .await;

    let WithBlobsAndMev {
        value: execution_payload,
        proofs,
        blobs,
        ..
    } = execution_payload
        .ok_or(Error::ExecutionPayloadNotAvailable)?
        .result;

